UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Present Simple [[b]]alışkanlığı[[/b]], Present Continuous ise [[b]]şu anı veya geçici dönemi[[/b]] anlatır — sinyal kelimelere bak:", "items": [{"heading": "Present Simple: Genel Gerçek ve Alışkanlık", "badge": "Sinyal Kelimeler", "body": [{"type": "text", "text": "Present Simple, [[dark]]GENEL GERÇEKLERİ[[/dark]], [[dark]]ALIŞKANLIKLARI[[/dark]] ve düzenli tekrarlanan eylemleri anlatır ve genellikle [[amber]]\"always, usually, often, every day, on Mondays\"[[/amber]] gibi sıklık zarflarıyla birlikte gelir."}]}, {"heading": "Present Continuous: Şu An veya Bu Dönem", "badge": "Sinyal Kelimeler", "body": [{"type": "text", "text": "Present Continuous ise [[dark]]ŞU AN KONUŞMA ANINDA[[/dark]] veya [[dark]]BU DÖNEMDE[[/dark]] (geçici olarak) süren bir eylemi anlatır ve [[amber]]\"now, at the moment, these days, currently, still\"[[/amber]] gibi ifadelerle birlikte gelir."}]}, {"heading": "Durum Fiilleri -ing Almaz", "badge": "Sık Tuzak", "body": [{"type": "text", "text": "Durum fiilleri ([[amber]]know, believe, like, love, hate, want, own, belong, understand[[/amber]]) duygu/düşünce/sahiplik bildirdiği için normalde [[bad]]\"-ing\"[[/bad]] ALMAZ, sürekli olsalar bile Present Simple ile kullanılır."}, {"type": "text", "text": "Bir boşlukta bu fiillerden biri varsa [[dark]]\"-ing\"[[/dark]] şıkkı doğrudan elenir."}]}], "examples": [{"sentence": "Water boils at 100 degrees Celsius at sea level.", "answer_word": "boils", "reasoning": "Bu evrensel, değişmeyen bir bilimsel gerçek olduğu için doğru cevap [[right]]\"boils\"[[/right]]tür (Present Simple)."}, {"sentence": "I know you're busy, but I really need your help with this report right now.", "answer_word": "need", "reasoning": "[[amber]]\"need\"[[/amber]] bir durum fiilidir (ihtiyaç/istek bildirir) ve [[b]]\"right now\"[[/b]] ifadesine rağmen [[bad]]\"-ing\"[[/bad]] ALAMAZ → doğru cevap [[right]]\"need\"[[/right]]dir, [[wrong]]\"am needing\"[[/wrong]] yanlıştır."}, {"sentence": "The committee meets every Thursday to review new applications.", "answer_word": "meets", "reasoning": "[[amber]]\"every Thursday\"[[/amber]] düzenli tekrarlanan bir rutini işaret ettiği için doğru cevap [[right]]\"meets\"[[/right]]tir (Present Simple); [[wrong]]\"is meeting\"[[/wrong]] yanlıştır çünkü burada o anlık geçici bir durum değil, kalıcı bir program anlatılıyor."}, {"sentence": "At the moment, no one knows exactly why the server crashed.", "answer_word": "knows", "reasoning": "[[amber]]\"know\"[[/amber]] bir DURUM fiilidir (bilgi/anlayış bildirir) ve [[b]]\"at the moment\"[[/b]] gibi genelde Present Continuous tetikleyen bir ifade olsa bile bu fiil [[bad]]\"-ing\"[[/bad]] ALAMAZ → doğru cevap [[right]]\"knows\"[[/right]]tur, [[wrong]]\"is knowing\"[[/wrong]] hiçbir bağlamda kullanılmaz."}]}$tagbd$::jsonb WHERE id = '20a78810-94a2-4e1a-823d-7ed8239e75a9';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]because[[/q]] + cümlecik ile [[q]]because of[[/q]] + isim öbeği arasındaki fark, [[q]]although/despite[[/q]] ayrımıyla birebir aynı mantıkla çalışır:", "items": [{"heading": "because vs because of", "badge": "Cümlecik mi, İsim mi?", "sub_rules": [{"condition": "Boşluktan sonra ÖZNE + YÜKLEM (tam cümlecik) geliyorsa:", "from": "there was a storm", "to": "because"}, {"condition": "Boşluktan sonra İSİM ÖBEĞİ veya -ing geliyorsa:", "from": "a storm", "to": "because of"}]}, {"heading": "so that vs in order to", "badge": "Amaç Bildiren Yapılar", "sub_rules": [{"condition": "[[q]]so that[[/q]] + özne + will/can/could geliyorsa:", "from": "she can finish", "to": "so that"}, {"condition": "[[q]]in order to[[/q]] + fiilin yalın hâli geliyorsa:", "from": "finish", "to": "in order to"}]}, {"heading": "so vs so that: Sonuç mu, Amaç mı?", "badge": "Anlam Ayrımı", "body": [{"type": "text", "text": "[[amber]]so[[/amber]] (sonuç, \"bu yüzden\") ile [[amber]]so that[[/amber]] (amaç, \"...sın diye\") farklı anlamlar taşır — cümlenin sebep mi sonuç mu, yoksa bir amaç mı anlattığına bakarak ikisini ayırt et."}]}], "examples": [{"sentence": "She left work early so that she could pick up her children from school.", "answer_word": "so that", "reasoning": "Boşluktan sonra özne+modal ([[b]]\"she could\"[[/b]]) var ve cümle bir [[dark]]AMAÇ[[/dark]] anlatıyor (erken çıkmasının sebebi çocukları almak) → doğru cevap [[right]]\"so that\"[[/right]]tır. [[wrong]]\"Because of\"[[/wrong]] yanlıştır çünkü ardından isim öbeği değil tam cümlecik gelmiş."}, {"sentence": "The flight was delayed because of a severe storm over the Atlantic.", "answer_word": "because of", "reasoning": "Boşluktan sonra isim öbeği ([[b]]\"a severe storm\"[[/b]]) geldiği için doğru cevap [[right]]\"because of\"[[/right]]tur; [[wrong]]\"because\"[[/wrong]] yanlıştır çünkü ardından özne+yüklemli tam bir cümlecik gelmemiştir (doğrusu [[b]]\"because there was a severe storm\"[[/b]] olurdu)."}, {"sentence": "The government introduced new regulations in order to reduce traffic congestion in the city center.", "answer_word": "in order to", "reasoning": "Boşluktan sonra fiilin yalın hali ([[b]]\"reduce\"[[/b]]) geldiği için doğru cevap [[right]]\"in order to\"[[/right]]dur; [[wrong]]\"so that\"[[/wrong]] burada yanlıştır çünkü ardından özne+yüklem değil, doğrudan bir fiil kökü gelmiştir."}, {"sentence": "The flight was cancelled because the airline could not find a replacement pilot in time.", "answer_word": "because", "reasoning": "Boşluktan sonra özne+yüklem içeren tam bir cümlecik ([[b]]\"the airline could not find...\"[[/b]]) geldiği için doğru cevap [[right]]\"because\"[[/right]]tir; [[wrong]]\"because of\"[[/wrong]] yanlıştır çünkü ardından isim öbeği değil tam bir cümlecik gelmiştir."}]}$tagbd$::jsonb WHERE id = 'b4a94169-96da-4bb3-84d1-3ead6fb9de59';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktan hemen sonraki ismin [[b]]sayılabilir çoğul[[/b]] mu yoksa [[b]]sayılamayan tekil[[/b]] mi olduğuna bak:", "items": [{"heading": "Sayılabilir mi, Sayılamaz mı?", "badge": "Temel Test", "sub_rules": [{"condition": "Sayılamayan isimlerle ([[amber]]information, advice, money, traffic, furniture[[/amber]] gibi tekil ve çoğul eki ALMAYAN isimlerle):", "from": "money", "to": "much / little"}, {"condition": "Sayılabilir çoğul isimlerle ([[amber]]students, cars, problems[[/amber]] gibi -s'li isimlerle):", "from": "students", "to": "many / few"}], "body": [{"type": "text", "text": "[[q]]a lot of[[/q]] / [[q]]lots of[[/q]] ise HER İKİSİYLE de sorunsuz kullanılabildiği için şıklarda güvenli bir seçenek gibi görünse de, soru genellikle [[b]]much/many/little/few[[/b]] arasındaki ayrımı test eder."}]}, {"heading": "a few / a little mi, few / little mi? Zıt Anlamlar", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "İkinci kritik ayrım: [[q]]\"a few/a little\"[[/q]] olumlu bir anlam taşır (\"birkaç tane var, yeterli\"), [[q]]\"few/little\"[[/q]] (a'sız) ise olumsuz bir anlam taşır (\"çok az, neredeyse yok\") — bu ikisi zıt anlamlıdır."}], "meaning_pairs": [[{"word": "a few / a little", "meaning": "birkaç tane var, yeterli (olumlu)"}, {"word": "few / little", "meaning": "çok az, neredeyse yok (olumsuz)", "variant": "wrong"}]], "warning_text": "Cümlenin olumlu mu olumsuz mu olduğuna bakmadan sadece \"a\" harfini es geçmek ya da eklemek, bu sorularda zıt anlamlı bir şıkkın seçilmesine yol açar."}], "examples": [{"sentence": "How much time do we have before the meeting starts?", "answer_word": "much", "reasoning": "[[amber]]\"time\"[[/amber]] sayılamayan bir isim olduğu için doğru cevap [[right]]\"much\"[[/right]]tır; [[wrong]]\"many\"[[/wrong]] sadece sayılabilir çoğul isimlerle ([[b]]\"How many minutes...\"[[/b]]) kullanılabilirdi."}, {"sentence": "She has a few friends here, so she rarely feels lonely.", "answer_word": "a few", "reasoning": "Burada olumlu bir anlam (yalnız hissetmiyor, demek ki yeterince arkadaşı var) olduğu için doğru cevap [[right]]\"a few\"[[/right]]dür; eğer [[b]]\"a\"[[/b]] olmadan sadece [[wrong]]\"few\"[[/wrong]] kullanılsaydı anlam \"neredeyse hiç arkadaşı yok\" olur ve cümlenin devamıyla ([[b]]\"rarely feels lonely\"[[/b]]) çelişirdi."}, {"sentence": "There isn't much traffic on the highway today, so we should arrive on time.", "answer_word": "much", "reasoning": "[[amber]]\"traffic\"[[/amber]] sayılamayan bir isimdir ve cümle OLUMSUZ olduğu için doğru cevap [[right]]\"much\"[[/right]]tır; [[wrong]]\"many\"[[/wrong]] sadece sayılabilir çoğul isimlerle kullanılabilir, [[b]]\"traffic\"[[/b]] gibi sayılamayan bir isimle asla kullanılmaz."}, {"sentence": "He has few close friends in this city, which makes him feel quite isolated.", "answer_word": "few", "reasoning": "[[b]]\"feel quite isolated\"[[/b]] (yalıtılmış/yalnız hissetmek) OLUMSUZ bir sonuç belirttiği için doğru cevap, [[b]]\"a\"[[/b]] olmadan kullanılan [[right]]\"few\"[[/right]]dür (neredeyse hiç yok anlamında); eğer [[wrong]]\"a few\"[[/wrong]] kullanılsaydı anlam \"yeterince arkadaşı var\" olur ve [[b]]\"isolated\"[[/b]] hissiyle çelişirdi."}]}$tagbd$::jsonb WHERE id = '9e721636-b34f-49bc-9293-3cbf1d292aa6';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Question tag kuralının temeli [[dark]]ZITLIK[[/dark]]tır: ana cümle OLUMLU ise etiket OLUMSUZ, ana cümle OLUMSUZ ise etiket OLUMLUdur:", "items": [{"heading": "Temel Kural: Zıtlık ve Yardımcı Fiil Eşleşmesi", "badge": "Ana Kural", "body": [{"type": "text", "text": "Etiketteki yardımcı fiil ana cümledeki yardımcı fiille/modal ile [[dark]]AYNI OLMAK ZORUNDADIR[[/dark]] ([[q]]\"They have finished, haven't they?\"[[/q]]); ana cümlede yardımcı fiil/modal YOKSA (yalın present/past simple), etikette [[amber]]do/does/did[[/amber]] kullanılır ([[q]]\"He plays football, doesn't he?\"[[/q]])."}, {"type": "example_check", "correct": "She is tired, isn't she?", "wrong_note": "ana cümle olumluysa etiket olumsuz olmalıdır"}]}, {"heading": "Düzensiz İstisnalar", "badge": "Sık Çıkan İstisnalar", "sub_rules": [{"condition": "[[q]]\"I am\"[[/q]] cümlesinin etiketi düzensiz olarak:", "from": "I am", "to": "aren't I"}, {"condition": "Emir cümlelerinin etiketi genellikle:", "from": "(emir cümlesi)", "to": "will you"}, {"condition": "[[q]]\"Let's\"[[/q]] ile başlayan tekliflerin etiketi:", "from": "Let's", "to": "shall we"}, {"condition": "[[q]]\"there is/are\"[[/q]] cümlelerinde özne yerine tekrar edilen:", "from": "there is/are", "to": "there"}]}], "examples": [{"sentence": "You haven't finished your homework yet, have you?", "answer_word": "have you", "reasoning": "Ana cümle olumsuz ([[amber]]\"haven't\"[[/amber]]) olduğu için etiket olumlu olmalı ve aynı yardımcı fiili kullanmalı → doğru cevap [[right]]\"have you\"[[/right]]dur, [[wrong]]\"haven't you\"[[/wrong]] değildir."}, {"sentence": "Let's go for a walk, shall we?", "answer_word": "shall we", "reasoning": "[[q]]\"Let's\"[[/q]] ile başlayan tekliflerde standart kural (özne+yardımcı fiil zıtlığı) uygulanmaz, sabit kalıp [[right]]\"shall we\"[[/right]] kullanılır — [[wrong]]\"don't we\"[[/wrong]] gibi bir cevap burada her zaman yanlıştır."}, {"sentence": "I'm the only one who noticed the mistake in the report, aren't I?", "answer_word": "aren't I", "reasoning": "[[q]]\"I am\"[[/q]] cümlesinin etiketi düzensiz olarak [[right]]\"aren't I\"[[/right]]dir ([[bad]]\"amn't I\"[[/bad]] biçimi yoktur) → doğru cevap [[right]]\"aren't I\"[[/right]]dir."}, {"sentence": "There isn't enough evidence to support this theory yet, is there?", "answer_word": "is there", "reasoning": "[[q]]\"there is/are\"[[/q]] cümlelerinde özne yerine [[amber]]\"there\"[[/amber]] tekrar edilir ve ana cümle olumsuz olduğu için etiket olumlu olmalı → doğru cevap [[right]]\"is there\"[[/right]]dir; [[wrong]]\"isn't there\"[[/wrong]] ya da özneyi [[b]]\"it\"[[/b]] ile değiştiren bir cevap burada yanlıştır."}]}$tagbd$::jsonb WHERE id = '85b23833-51c5-4d21-bfa3-94cf0bc4d2c2';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Doğrudan bir soru cümlesinde kelime sırası [[q]]SORU KELİMESİ + YARDIMCI FİİL/MODAL + ÖZNE + ANA FİİL[[/q]] şeklindedir, ama bu cümle başka bir cümlenin içine (gömülü soru) girdiğinde sıra değişir:", "items": [{"heading": "Doğrudan Soru: Devrik Sıra", "badge": "Bağımsız Soru", "body": [{"type": "text", "text": "Doğrudan bir soru cümlesinde kelime sırası [[q]]SORU KELİMESİ (varsa) + YARDIMCI FİİL/MODAL + ÖZNE + ANA FİİL[[/q]] şeklindedir."}, {"type": "example_check", "correct": "Where did she go?", "wrong_note": "bağımsız bir soruda devrik sıra kullanılır"}]}, {"heading": "Gömülü Soru: Düz Cümle Sırası", "badge": "Tuzak Noktası", "body": [{"type": "text", "text": "Bu cümle [[dark]]BAŞKA BİR CÜMLENİN İÇİNE[[/dark]] (dolaylı/gömülü soru) girdiğinde kelime sırası [[q]]DÜZ CÜMLE (ÖZNE + YÜKLEM)[[/q]] sırasına döner ve [[amber]]\"do/does/did\"[[/amber]] yardımcı fiili [[dark]]TAMAMEN DÜŞER[[/dark]]."}, {"type": "example_check", "correct": "I wonder where she went", "wrong_note": "\"I wonder where did she go\" YANLIŞTIR"}, {"type": "text", "text": "Bu, YDS'nin [[q]]\"Could you tell me...\", \"I don't know...\", \"I wonder...\"[[/q]] gibi ifadelerle başlayan cümlelerde en sık kurduğu tuzaktır: şıklarda ters çevrilmiş (inverted) bir yapı görürsen ve bu yapı bu tür bir ifadenin İÇİNDEYSE, o şık kesinlikle yanlıştır."}]}], "examples": [{"sentence": "Could you tell me where the nearest bank is?", "answer_word": "where the nearest bank is", "reasoning": "Doğru cevap [[right]]\"where the nearest bank is\"[[/right]]tir, [[wrong]]\"where is the nearest bank\"[[/wrong]] değildir — çünkü soru [[b]]\"Could you tell me\"[[/b]] ifadesinin içine gömülmüştür ve düz cümle sırasına dönmelidir."}, {"sentence": "Who did you invite to the party last night?", "answer_word": "Who did you invite", "reasoning": "Bağımsız bir soru cümlesi olduğu için burada normal soru devrik sırası geçerlidir, doğru cevap [[right]]\"Who did you invite\"[[/right]]dır; bu cümle [[b]]\"I wonder\"[[/b]] gibi bir ifadenin içine girseydi ([[b]]\"I wonder who you invited to the party\"[[/b]]), devrik yapı kaybolurdu."}, {"sentence": "I don't know how far it is from the station to the museum.", "answer_word": "how far it is", "reasoning": "Soru [[b]]\"I don't know\"[[/b]] ifadesinin içine gömülü olduğu için devrik yapı kaybolur → doğru cevap [[right]]\"how far it is\"[[/right]]tir, [[wrong]]\"how far is it\"[[/wrong]] değildir çünkü bu bağımsız bir soru değildir."}, {"sentence": "Who spoke at the conference yesterday that made such a strong impression on everyone?", "answer_word": "Who spoke", "reasoning": "Bu cümle bağımsız bir soru olduğu için normal devrik soru sırası geçerlidir → doğru cevap [[right]]\"Who spoke\"[[/right]]tur; bu cümle [[b]]\"Do you remember...\"[[/b]] gibi bir ifadenin içine gömülseydi ([[b]]\"Do you remember who spoke at the conference...\"[[/b]]), devrik sıra kaybolurdu."}]}$tagbd$::jsonb WHERE id = '3b7fc300-cd9c-450b-aeaa-ea2e7e4f89b6';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[amber]]\"fairly\"[[/amber]] ve [[amber]]\"rather\"[[/amber]] \"oldukça\" anlamında hafif bir derece artışı yapar, ama [[amber]]\"quite\"[[/amber]] sıfatın türüne göre anlam değiştirir:", "items": [{"heading": "fairly vs rather: Ton Farkı", "badge": "Derece Zarfları", "body": [{"type": "text", "text": "[[amber]]\"fairly\"[[/amber]] ve [[amber]]\"rather\"[[/amber]] sıfat/zarfın yoğunluğunu \"oldukça\" anlamında hafifçe artırır."}, {"type": "text", "text": "[[amber]]\"rather\"[[/amber]] genellikle [[b]]BEKLENENDEN FAZLA[[/b]] veya OLUMSUZ bir tonla kullanılır ([[q]]\"rather expensive\"[[/q]] = beklenenden pahalı), [[amber]]\"fairly\"[[/amber]] ise daha nötr ve [[b]]ORTA DÜZEY[[/b]] bir dereceyi belirtir."}]}, {"heading": "quite'in İki Yüzü: Derecelenebilir mi, Mutlak mı?", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[amber]]\"quite\"[[/amber]] İKİ FARKLI anlamda kullanılabilir — hangi sıfatla geldiğine bağlı olarak anlamı tamamen değişir."}], "meaning_pairs": [[{"word": "quite + derecelenebilir sıfat (big, good, cold)", "meaning": "oldukça"}, {"word": "quite + mutlak sıfat (perfect, impossible, certain)", "meaning": "tamamen", "variant": "wrong"}]], "warning_text": "Bir boşlukta \"quite\" seçeneği varsa, sıfatın derecelenebilir mi yoksa mutlak/derecelenemeyen mi olduğuna bakarak anlamı belirlemek gerekir; bu ayrımı atlamak YDS'de klasik bir tuzaktır."}], "examples": [{"sentence": "The hotel room was rather small for the price we paid, which disappointed us.", "answer_word": "rather", "reasoning": "Beklenenden daha olumsuz bir ton ve hafif bir eleştiri var → doğru cevap [[right]]\"rather\"[[/right]]dır."}, {"sentence": "His explanation of the theory was quite perfect; I couldn't find a single flaw in it.", "answer_word": "quite", "reasoning": "[[amber]]\"perfect\"[[/amber]] derecelenemeyen (mutlak) bir sıfattır, bu yüzden buradaki [[right]]\"quite\"[[/right]] \"oldukça\" değil \"tamamen\" anlamına gelir → doğru cevap [[right]]\"quite\"[[/right]]tır; [[wrong]]\"fairly\"[[/wrong]] burada kullanılamaz çünkü \"fairly perfect\" mutlak bir sıfatla çelişen garip bir ifadedir."}, {"sentence": "The lecture was fairly interesting, though I expected it to be more engaging given the professor's reputation.", "answer_word": "fairly", "reasoning": "Cümledeki [[b]]\"though\"[[/b]] ve hafif hayal kırıklığı tonu, beklenenden AZ bir yoğunluğu işaret ediyor, nötr bir orta derece anlatılıyor → doğru cevap [[right]]\"fairly\"[[/right]]dir; [[wrong]]\"rather\"[[/wrong]] burada daha güçlü bir olumsuz vurgu taşırdı ve cümledeki ölçülü tona \"fairly\" kadar doğal uymaz."}, {"sentence": "I'm quite certain that she already knows about the surprise party; she's been acting strangely all week.", "answer_word": "quite", "reasoning": "[[amber]]\"certain\"[[/amber]] derecelenemeyen (mutlak) bir sıfattır, bu yüzden buradaki [[right]]\"quite\"[[/right]] \"oldukça\" değil \"neredeyse tamamen\" anlamına gelir → doğru cevap [[right]]\"quite\"[[/right]]tır; [[wrong]]\"rather\"[[/wrong]] mutlak sıfatlarla doğal bir şekilde bir araya gelmediği için burada tercih edilmez."}]}$tagbd$::jsonb WHERE id = '7ea32cae-1d01-4bf9-b7c2-32d8f887396c';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Dönüşlü zamir ([[amber]]myself, himself, themselves...[[/amber]]) SADECE eylemi yapan ile eylemden etkilenen kişi [[dark]]AYNI[[/dark]] olduğunda kullanılır:", "items": [{"heading": "Özne = Nesne Testi", "badge": "Temel Kural", "body": [{"type": "text", "text": "Dönüşlü zamir ([[amber]]myself, yourself, himself, herself, itself, ourselves, yourselves, themselves[[/amber]]) SADECE eylemi yapan ile eylemden etkilenen kişi [[dark]]AYNI[[/dark]] olduğunda kullanılır."}, {"type": "example_check", "correct": "He cut himself while cooking", "wrong_note": "özne ile nesne farklı kişilerse normal kişi zamiri (him, her, them...) kullanılır"}, {"type": "text", "text": "Özne ile nesne FARKLI kişilerse normal kişi zamiri kullanılır — [[q]]\"He cut him\"[[/q]] demek, BAŞKA birini kestiği anlamına gelir."}]}, {"heading": "Vurgu Kullanımı: Bizzat, Kendisi", "badge": "İkincil Kullanım", "body": [{"type": "text", "text": "Dönüşlü zamirler [[dark]]VURGU[[/dark]] amacıyla da kullanılır, \"bizzat, kendisi\" anlamında ([[q]]\"I did it myself\"[[/q]] = bunu bizzat ben yaptım, başkası yapmadı)."}, {"type": "text", "text": "Bu kullanımda zamir gramatik olarak [[b]]ZORUNLU DEĞİLDİR[[/b]], cümleden çıkarılabilir, sadece vurgu katar."}]}], "examples": [{"sentence": "The manager blamed himself for the project's failure, even though the mistake was not his fault.", "answer_word": "himself", "reasoning": "Yöneticinin [[b]]KENDİSİNİ[[/b]] suçladığı (özne=nesne) anlatıldığı için doğru cevap [[right]]\"himself\"[[/right]]tir; [[wrong]]\"him\"[[/wrong]] kullanmak başka bir erkeği suçladığı anlamına gelir ki bu cümlenin bağlamıyla çelişir."}, {"sentence": "I didn't hire an assistant; I handled all the paperwork myself.", "answer_word": "myself", "reasoning": "Burada \"bizzat kendim\" vurgusu yapıldığı için doğru cevap [[right]]\"myself\"[[/right]]tir ve cümleden çıkarılsa bile cümle gramatik olarak doğru kalır, sadece vurgu kaybolur."}, {"sentence": "The company's CEO congratulated himself on securing the biggest deal of the year, since he had led the negotiations personally.", "answer_word": "himself", "reasoning": "Özne (CEO) ile nesne [[dark]]AYNI[[/dark]] kişi olduğu (kendini kutladı) anlatıldığı için doğru cevap [[right]]\"himself\"[[/right]]tir; [[wrong]]\"him\"[[/wrong]] kullanmak CEO'nun BAŞKA bir adamı kutladığı anlamına gelir ki bu, [[b]]\"he had led the negotiations personally\"[[/b]] ifadesiyle çelişir."}, {"sentence": "The software update installs itself automatically whenever a new version is released, without requiring any action from the user.", "answer_word": "itself", "reasoning": "Özne (the software update) cansız bir nesnedir ve eylem [[dark]]KENDİ KENDİNE[[/dark]] gerçekleştiği için doğru cevap [[right]]\"itself\"[[/right]]tir; bu kullanımda zamir vurgu amaçlıdır (\"kendi kendine\") ve cümleden çıkarılsa da cümle gramatik olarak doğru kalır, sadece vurgu kaybolur."}]}$tagbd$::jsonb WHERE id = '613cf372-67df-4091-83ae-e222b39b1430';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "İlgi zamiri ([[q]]who/which/that/whose/where/when[[/q]]) seçimi iki adımlı bir kontrolden geçer: önce boşluktan [[b]]ÖNCEKİ[[/b]] ismin türüne, sonra boşluktan [[b]]SONRAKİ[[/b]] yapıya bakılır:", "items": [{"heading": "Önceki İsmin Türü: İnsan / Nesne / Aitlik", "badge": "İsim Türüne Göre", "sub_rules": [{"condition": "Önceki isim [[amber]]insan[[/amber]] ise:", "from": "insan", "to": "who / that"}, {"condition": "Önceki isim [[amber]]nesne veya kavram[[/amber]] ise:", "from": "nesne/kavram", "to": "which / that"}, {"condition": "Önceki isim bir şeye [[amber]]aitlik[[/amber]] bildiriyorsa:", "from": "aitlik", "to": "whose"}]}, {"heading": "Önceki İsmin Türü: Yer / Zaman", "badge": "İsim Türüne Göre", "sub_rules": [{"condition": "Önceki isim bir [[amber]]yer[[/amber]] ise:", "from": "yer", "to": "where"}, {"condition": "Önceki isim bir [[amber]]zaman[[/amber]] ifadesi ise:", "from": "zaman", "to": "when"}]}, {"heading": "Sonraki Yapıya Bakarak Özne/Nesne Testi", "badge": "Özne mi, Nesne mi?", "body": [{"type": "text", "text": "Boşluktan hemen sonra bir [[amber]]YÜKLEM[[/amber]] geliyorsa zamir [[dark]]ÖZNE[[/dark]] konumundadır ([[q]]who/which/that[[/q]]) ve bu durumda [[bad]]ATILAMAZ[[/bad]]."}, {"type": "text", "text": "Önce başka bir [[amber]]ÖZNE + YÜKLEM[[/amber]] geliyorsa zamir [[dark]]NESNE[[/dark]] konumundadır ([[q]]whom/which/that[[/q]]) ve defining clause'da [[ok]]ATILABİLİR[[/ok]]."}, {"type": "example_check", "correct": "The report she submitted yesterday contained several errors", "wrong_note": "zamir özne konumunda olsaydı (\"The report ___ contained several errors was submitted yesterday\") atılamazdı"}]}, {"heading": "Edat + which/whom Kalıbı", "badge": "Edat Tuzağı", "body": [{"type": "text", "text": "Cümlede bir [[amber]]edat[[/amber]] varsa [[q]]edat + which/whom[[/q]] kalıbını ara, ör. [[pair]]the project on which he worked[[/pair]]."}, {"type": "text", "text": "Edat cümle başına geldiğinde [[bad]]\"that\"[[/bad]] asla kullanılamaz: [[bad]]\"in that\"[[/bad]] yanlış, [[ok]]\"in which\"[[/ok]] doğrudur."}, {"type": "example_check", "correct": "the project on which he worked", "wrong_note": "\"in that\" gibi bir kullanım yanlıştır, doğrusu \"in which\"tir"}]}], "examples": [{"sentence": "The report that she submitted yesterday contained several errors.", "answer_word": "that", "reasoning": "Boşluktan sonra [[b]]\"she submitted\"[[/b]] (özne+yüklem) geldiği için zamir [[dark]]NESNE[[/dark]] konumundadır → doğru cevap [[right]]\"that\"[[/right]] (ya da \"which\") olup defining clause olduğu için tamamen de atılabilir. Eğer cümle \"The report ___ contained several errors was submitted yesterday\" olsaydı, boşluktan hemen sonra yüklem (\"contained\") geldiği için zamir [[dark]]ÖZNE[[/dark]] konumunda olur ve [[wrong]]atılamaz[[/wrong]]dı."}, {"sentence": "The engineer who designed this bridge studied at a prestigious university.", "answer_word": "who", "reasoning": "Boşluktan hemen sonra yüklem (\"designed\") geldiği için zamir [[dark]]ÖZNE[[/dark]] konumundadır → doğru cevap [[right]]\"who\"[[/right]] (ya da \"that\") olup [[wrong]]ATILAMAZ[[/wrong]]; zamiri tamamen çıkarmak (\"The engineer designed this bridge studied...\") cümleyi anlaşılmaz hale getirir çünkü özne boşlukta kalır."}, {"sentence": "The author, whose latest novel won several international awards, will be giving a talk at the university next week.", "answer_word": "whose", "reasoning": "Boşluktan sonra \"latest novel\" (bir isim) gelmesi [[dark]]AİTLİK[[/dark]] bildiren bir zamir gerektiğini gösterir → doğru cevap [[right]]\"whose\"[[/right]]tur; [[wrong]]\"who\"[[/wrong]] veya [[wrong]]\"which\"[[/wrong]] burada aitlik anlamı taşımadığı için yanlıştır."}, {"sentence": "This is the laboratory where the vaccine was first developed and tested.", "answer_word": "where", "reasoning": "Boşluktan sonra tam bir özne+yüklem (\"the vaccine was first developed\") geliyor ve anlam bir [[dark]]YERE[[/dark]] işaret ediyor → doğru cevap [[right]]\"where\"[[/right]]dir; [[wrong]]\"which\"[[/wrong]] kullanılacaksa önüne mutlaka bir edat gelmesi gerekirdi ([[q]]\"in which\"[[/q]]), yalın \"which\" burada yetersiz kalır."}]}$tagbd$::jsonb WHERE id = '7c22d868-2e33-4369-b962-0417ead3b258';
